function 建立原生物件尋路器({ getWorld, getRenderer, readHud, interactForge, now = Date.now, radius = 200, verify=()=>{}, move=(world,x,y)=>world.moveOnly(x,y), onMove=()=>{} }) {
  let pending = null;
  return {
    reset() { pending = null; },
    tick(target, dialogMatches) {
      const world = getWorld();
      const hud = readHud();if(world)verify(world);
      if (!world?.player || world.regionId !== target.regionId || !hud ||
          now() - hud.seenAt > 3500 || ![hud.x, hud.y].every(Number.isFinite)) {
        return { state: 'waiting', message: '等待正確地圖與即時座標' };
      }
      const objects = target.facilityId ? world.region?.decorations : world.npcs;
      const object = target.forge ? world.region?.workshop?.forge : Array.isArray(objects) && objects.find(item => target.facilityId
        ? item.kind === 'guildFacility' && item.facilityId === target.facilityId
        : item.id === target.id);
      if (!object || ![object.x, object.y].every(Number.isFinite)) {
        return { state: 'blocked', message: `目前地圖未找到 ${target.name} 的原生物件` };
      }
      if (dialogMatches()) return { state: 'opened' };
      const key = `${target.regionId}:${target.forge ? 'forge' : target.facilityId || target.id}`;
      if (pending?.key !== key) pending = { key, movedAt: 0, sentAt: 0 };
      const distance = Math.hypot(hud.x - object.x, hud.y - object.y);
      if (pending.sentAt) return { state: 'waiting', message: `已送出 ${target.name} 對話，等待畫面` };
      if (distance > (target.forge ? Math.min(radius,80) : radius)) {
        if (typeof world.moveOnly !== 'function') return { state: 'blocked', message: '遊戲移動入口不可用' };
        if (!pending.movedAt || now() - pending.movedAt >= 5000) {
          verify(world);move(world,object.x,object.y);onMove(world);
          pending.movedAt = now();
        }
        return { state: 'moving', distance, message: `前往 ${target.name}，距離 ${Math.ceil(distance)}` };
      }
      verify(world);if (world.pendingSkill) world.cancelPendingSkill?.();verify(world);
      if (target.forge) {
        if (typeof interactForge !== 'function') return { state: 'blocked', message: '工坊互動入口不可用' };
        verify(world);if (interactForge(object, world) !== true) return { state: 'waiting', message: '等待工坊互動可用' };
      } else if (target.facilityId) {
        const renderer = getRenderer();
        if (world.guildTerritoryContext?.visiting) return { state: 'blocked', message: '拜訪他人公會時不執行互動' };
        if (typeof renderer?.onGuildFacilityClick !== 'function') return { state: 'blocked', message: '公會物件互動入口不可用' };
        verify(world);renderer.onGuildFacilityClick(object);
      } else {
        if (typeof world.approachNpc !== 'function') return { state: 'blocked', message: 'NPC 對話入口不可用' };
        verify(world);world.approachNpc(object.id);
      }
      pending.sentAt = now();
      return { state: 'sent', distance, message: `距離 ${Math.ceil(distance)}，已請求 ${target.name} 對話` };
    }
  };
}

