    const quantities=entries('.crafting-action-grid input',props=>craftInt(props.qty,1)&&craftInt(props.maxQty)&&typeof props.disabled==='boolean'&&typeof props.onChange==='function',current);
    const actions=entries('.crafting-action-grid button.btn',props=>props.className==='btn'&&typeof props.disabled==='boolean'&&typeof props.onClick==='function',current);
    if(quantities.length!==1||actions.length!==1)return null;
