  return {root,status,owner,selected,pending,
    open(){verify();if(owner())return true;if(!menu.prepare())return false;menu.open();verify();return Boolean(owner());},
    select(target){verify();const current=owner();if(!current)return false;const values=readNativeViewStateValues(current.node);if(!values)return false;if(selected(target))return true;
      const tabs=entries('.auto-gather-tab',current,(props,node)=>node.key===target.skill&&typeof props.onClick==='function');
      const materials=entries('.auto-gather-material',current,(props,node)=>node.key===target.itemId&&typeof props.onClick==='function');
      if(materials.length===1){materials[0].props.onClick();verify();}else if(tabs.length===1){tabs[0].props.onClick();verify();}return false;},
    start(target){verify();const current=selected(target),snapshot=status();if(!current||current.button.disabled||!snapshot||snapshot.active||snapshot.casting)return false;current.button.onClick();verify();return true;},
    stop(itemId){verify();const snapshot=status(),current=root();if(!snapshot?.active||snapshot.itemId!==itemId||!current)return false;
      const hud=readNativeViewEntries({document,selector:'.auto-gather-hud button',accept:(props,node)=>props.status?.active===true&&props.status.itemId===itemId&&gatherBelongs(node,current.node)});if(hud.length!==1)return false;
      const buttons=entries('.auto-gather-hud button',hud[0],props=>typeof props.onClick==='function'&&props.disabled!==true);if(buttons.length!==1)return false;buttons[0].props.onClick();verify();return true;},
    close(){verify();const current=owner();if(!current)return true;current.props.onClose();verify();return !owner();}
  };
