function nativeSweepRecordKey(record){if(record.scope!=='dungeon-sweep'||record.protocol!==1||!/^\d{4}-\d{2}-\d{2}$/.test(record.day))throw new Error('原生掃蕩紀錄未確認');return 'native-sweep:'+record.day+':all';}
