  function restoreRunCount(runId,count){host.assert(getContext(),{allowPending:true});if(typeof runId!=='string'||!runId||!Number.isSafeInteger(count)||count<0)throw new Error('副本接續計次無效');const previous=state.runCounts.map(row=>({...row}));const row=state.runCounts.find(row=>row.runId===runId);if(row){row.count=Math.max(row.count,count);row.at=now();}else state.runCounts.push({runId,count,at:now()});try{persist();}catch(error){state.runCounts=previous;throw error;}}

  function sync(){const rows=pending(),previous=host.currentPending();if(rows.length)host.pending({kind:'dungeon-result-journal',taskKind:'dungeon',sourceRole,entries:rows.map(([key,record])=>({key,...record}))});else if(previous?.kind==='dungeon-result-journal'&&previous.sourceRole===sourceRole)host.pending(null);}
