function createCoreTransport(request,{timeout=4000}={}) {
  const paths = new Set(['pair','register','exchange','unregister']);
  return async (endpoint,payload,token=null) => {
    if(!paths.has(endpoint)) throw new ControlError('invalid_endpoint','未支援的核心接口');
    if(jsonBytes(payload)>262144) throw new ControlError('request_too_large','請求超過256KiB');
    const data=await request({method:'POST',url:`http://127.0.0.1:17342/api/v1/assistant/${endpoint}`,timeout,
      headers:{'Content-Type':'application/json; charset=utf-8',...(token?{Authorization:`Bearer ${token}`}:{})},data:JSON.stringify(payload)});
    if(new TextEncoder().encode(data.responseText).length>262144) throw new ControlError('response_too_large','核心回應超過256KiB');
    let parsed;try{parsed=JSON.parse(data.responseText);}catch{throw new ControlError(data.status<200||data.status>=300?'core_http_error':'invalid_response',`核心回應 HTTP ${data.status}，不是JSON`);}
    if(!parsed || typeof parsed!=='object' || Array.isArray(parsed))throw new ControlError('invalid_response','核心回應形狀無效');
    if(parsed.error) throw new ControlError(parsed.error.code||'core_error',parsed.error.message||'核心回應錯誤');
    if(data.status<200 || data.status>=300) throw new ControlError('core_http_error',`核心回應 HTTP ${data.status}`);
    if((endpoint==='pair'||endpoint==='register') && parsed.contractVersion!==undefined && parsed.contractVersion!==CONTRACT_VERSION) throw new ControlError('contract_mismatch','通訊協定不相容');
    return parsed;
  };
}



const MANUAL_TASK_CAPABILITY='task.start:manual-task:v1';
const MANUAL_TASK_SCHEMA_VERSION=1;
const MANUAL_RESUME_LOCATION_CAPABILITY='task.resume:location:v1';
