function validateRecoverySettings(value){if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).some(k=>!['enabled','maxAttempts','backoffMs','tasks'].includes(k)))throw new ControlError('invalid_recovery','恢復設定格式無效');if(value.enabled!==undefined&&typeof value.enabled!=='boolean')throw new ControlError('invalid_recovery','恢復開關無效');if(value.maxAttempts!==undefined&&(!Number.isInteger(value.maxAttempts)||value.maxAttempts<0||value.maxAttempts>2))throw new ControlError('invalid_recovery','自動重整上限須為0至2次');if(value.backoffMs!==undefined&&(!Number.isInteger(value.backoffMs)||value.backoffMs<60000||value.backoffMs>3600000))throw new ControlError('invalid_recovery','重整退避須為60至3600秒');if(value.tasks!==undefined&&(!value.tasks||typeof value.tasks!=='object'||Array.isArray(value.tasks)||Object.entries(value.tasks).some(([kind,on])=>!['battle','daily','boss'].includes(kind)||typeof on!=='boolean')))throw new ControlError('invalid_recovery','來源恢復開關無效');return true;}
