function validateDeliveryEntries(characterId,value){
  if(!Array.isArray(value)||value.length>30||value.some(x=>!x||x.characterId!==characterId||typeof x.resultId!=='string'||!x.resultId||typeof x.runId!=='string'||!x.runId||!x.result||typeof x.result!=='object'||x._deliveryNext!==undefined&&(!Number.isSafeInteger(x._deliveryNext)||x._deliveryNext<0))||new Set(value.map(x=>x.resultId)).size!==value.length||new TextEncoder().encode(JSON.stringify(value.map(({_deliveryNext,...record})=>record))).length>2097152)throw new ControlError('corrupt_data','待交付成果損壞或超限，保留原資料');
  for(const entry of value){const {_deliveryNext,...record}=entry,total=Math.ceil(JSON.stringify(record).length/8192);if(_deliveryNext!==undefined&&_deliveryNext>=total)throw new ControlError('corrupt_data','成果分段進度無效，保留原資料');}
  return value;
}
