  if(!action||typeof action!=='object'||typeof action.kind!=='string'||action.taskKind!==taskKind)throw new ControlError('invalid_pending','來源未明操作格式不符');
  if(previous&&(previous.taskKind!==taskKind||previous.characterId!==characterId||previous.kind!==action.kind||previous.sourceRole!==action.sourceRole))throw new ControlError('pending_conflict','尚有另一操作待核對，禁止覆寫');
  if(c.active&&c.active.kind!==taskKind)throw new ControlError('pending_conflict','另一任務正在執行，禁止新增未明操作');
  if(!previous&&(!context||context.characterId!==characterId||typeof context.runId!=='string'||!context.runId))throw new ControlError('pending_without_run','未明操作缺少原始執行身分');
  if(previous&&context&&previous.runId!==context.runId)throw new ControlError('pending_conflict','未明操作屬於另一執行，禁止覆寫');
  c.pending={...structuredClone(action),taskKind,characterId,runId:previous?.runId??context.runId,pageEpoch:previous?.pageEpoch??context.pageEpoch};
