        const next=plots.find(plot=>nativeHarvestIds.includes(plot.plotId)&&gardenStage(plot)==='mature');
        if(next){await nativePlotAction(next,'harvest');statusText='收成 '+next.plotId;return;}
        if(plots.some(plot=>nativeHarvestIds.includes(plot.plotId)&&gardenStage(plot)!=='empty')){pauseUnclear('收成菜圃狀態已改變');return;}
