    box.style.left = `${Math.min(innerWidth - 242, Math.max(8, rect.right - 230))}px`;
    box.style.top = `${Math.max(8, Math.min(innerHeight - 330, rect.top > 330 ? rect.top - 320 : rect.bottom + 8))}px`;

    const title = document.createElement('div');
