   if(w.autoBattle!==true||t>=until){requestStop();stage='closing';since=t;return {busy:true,message:'關閉原生 AUTO，準備腳本戰鬥'};}
   return {busy:true,message:'啟動寵物：AUTO '+Math.ceil((until-t)/1000)+' 秒'};
