  function movementBlocked(){return roundValue('movementBlocked',()=>!![...document.querySelectorAll('dialog[open]')].some(el=>el.id!==ID+'-records'&&(el.id!==ID+'-settings'||el.dataset.readonly!=='true'))||!!document.activeElement?.closest('input,textarea,select,[contenteditable="true"]'))}

  // 只讀取當前隊伍與小地圖 DOM，不保存固定玩家排除名單。
  function currentMapName(hud=readHud()){return compactMapLabel(hud.where.split(/CH\.?\s*\d+/i)[0])}
  function currentChannel(hud=readHud()){return readNativeWorldFacts(PAGE.__world,{document,getWorld:()=>PAGE.__world}).channel??0;}
  function locationKey(hud){return currentMapName(hud)+'@'+currentChannel(hud)}
  function syncPending(){const raw=roundValue('connection',connectionState);return raw.sync&&!(run?.syncUiReleased===syncPlaceKey()&&nativeArrivalReady()&&!raw.disconnected)}
  function syncPlaceKey(){const w=PAGE.__world;return w?[w.charId,w.regionId,w.instanceId,readNativeWorldFacts(w,{document,getWorld:()=>PAGE.__world}).channelId,currentMapName()].join('|'):'';}
  function nativeArrivalReady(){const w=PAGE.__world;return !!w?.regionId&&!!w?.player&&Number(w.player.hp)>0&&!w.dead&&worldResourcesReady()&&typeof w.isWorldInteractionLocked==='function'&&!w.isWorldInteractionLocked()&&[w.player.x,w.player.y].every(Number.isFinite)&&trainingMap(readHud())&&autoAreaState()==='field';}
  function reconcileRiftArrival(hud){
    if(currentMode()||routeDestination()!=='rift'||!run.target||!atNormalTarget(hud,run.target))return;
    if(!['navigate','area','branch','areaTravel','riftTravel','riftArrival','room','arrival'].includes(run.phase))return;
    // 同步後仍在一般圖，丟棄舊地圖選取／已送傳送旗標，重新選裂痕；不假定已到裂痕。
    const syncState={syncUiReleased:run.syncUiReleased,syncReadyAt:run.syncReadyAt,syncReadyPlace:run.syncReadyPlace};resetNavigation();Object.assign(run,syncState);run.phase='area';run.routeAreaStartedAt=Date.now();run.message='已確認一般地圖，重新接續裂痕分支';
  }
  function trainingMap(hud){if(currentMode())return autoAreaState()==='field';const name=currentMapName(hud);return LEVELS.some(t=>name===compactMapLabel(t.name)||t.rifts.some(b=>name===compactMapLabel(t.world+'・裂痕 '+b)))}
  function leaderTarget(hud){if(currentMode()&&!run?.worldRecovery)return run.currentLocation===locationKey(hud);return nativeChannels.destinationConfirmed(routeDestination()==='normal'?run.target.name:run.target.world+'・裂痕 '+routeBranch());}
  function routeDestination(){if(run?.worldRecovery)return ['wait','home'].includes(run.worldRecovery.stage)?'normal':run.worldRecovery.destination;return run?.returnReason||run?.recoveryHome||run?.noExpRecovery?.stage==='home'||!!run?.autoRest?'normal':settings.destination}
  function routeBranch(){return run?.worldRecovery?.branch??settings.branch}
