      for(const cleanup of [()=>arrivalAuto.cancel(),()=>cancelMovePair(),()=>releaseNativeFollow(),()=>battleTactics.reset(),()=>detachKillCounter(),()=>stopRunResources(),()=>host.cancelAll()])try{cleanup();}catch{}
