      if(stage==='world'){run.worldTravelRequested=false;run.phase='area';run.routeAreaStartedAt=Date.now();}
      else if(rift){run.phase='room';run.roomWaitAt=Date.now();run.roomSelectionAt=0;run.roomEntered=false;}
