  function validate(options={}) {
    if(!options || typeof options!=='object' || Array.isArray(options))throw new Error('戰鬥設定格式無效');
    const allowed=new Set([...Object.keys(DEFAULTS),'combatMode','dodge','guildSkills']);
    for(const key of Object.keys(options))if(!allowed.has(key))throw new Error('未知戰鬥設定：'+key);
    for(const key of ['expScrollEnabled','cancelAvoidance','petAutoWake','autoFollowLeader','characterPickup','dodge','guildSkills'])if(options[key]!==undefined&&typeof options[key]!=='boolean')throw new Error('戰鬥勾選值無效：'+key);
    if(options.role!==undefined&&!['leader','member'].includes(options.role))throw new Error('隊伍角色無效');
    if(options.memberMode!==undefined&&!['interval','orbit','care'].includes(options.memberMode))throw new Error('隊員模式無效');
    if(options.combatMode!==undefined&&!['normal','efficient'].includes(options.combatMode))throw new Error('戰鬥模式無效');
    if(options.level!==undefined&&options.level!=='current'&&!LEVELS.some(v=>v.lv===options.level))throw new Error('目標等級無效');
    if(options.destination!==undefined&&!['normal','rift'].includes(options.destination))throw new Error('目的地無效');
    if(options.branch!==undefined&&!['','I','II','III','IV'].includes(options.branch))throw new Error('裂痕分支無效');
    for(const key of ['minutes','restAfter','restMinutes','maxRevives','expScrollTarget','followNear','followFar'])if(options[key]!==undefined&&(!Number.isFinite(options[key])||options[key]<0))throw new Error('戰鬥數值無效：'+key);
    const near=options.followNear??settings.followNear,far=options.followFar??settings.followFar;
    if(near>=far)throw new Error('跟隨遠距離必須大於近距離');
    if(options.potions!==undefined){if(!Array.isArray(options.potions)||options.potions.length!==4)throw new Error('需要四格補品設定');for(const p of options.potions){if(!p||typeof p.on!=='boolean'||!['hp','sp','item'].includes(p.type)||!Number.isFinite(p.threshold)||p.threshold<1||p.threshold>100||p.interval!==undefined&&(!Number.isFinite(p.interval)||p.interval<0)||Object.keys(p).some(k=>!['on','type','threshold','interval'].includes(k)))throw new Error('補品格設定無效');}}
    return true;
  }
