    if(!opened){finishRecipe();return;}
    await nativeOperationStep('討伐自動戰鬥補充卷',()=>nativeActions.runCertificateAuto(),result=>'自動戰鬥補充卷今日三次額度已用完（原生 '+result.used+'/3）');
