  const eligible=w=>scopeKind==='world'?['open','dungeon'].includes(w?.mode)&&typeof w.regionId==='string'&&w.regionId&&!w.region?.safeZone&&!w.region?.isVillage:w?.mode==='dungeon'&&typeof w.dungeonId==='string'&&w.dungeonId&&typeof w.instanceId==='string'&&w.instanceId;
