    const record={kind:'owned-auto-start',taskKind,sourceRole,sentAt:Date.now(),flowSentAt:clock(),...scope(w)};
    host.pending(record);host.assert(c,{allowPending:true});const saved=host.currentPending();
    if(world()!==w||!same(saved,w)||!eligible(w)||w.autoBattle!==false||w.autoBattlePendingAction||w.dead||!(w.player.hp>0)||w.isWorldInteractionLocked?.()!==false||blocked())throw new Error('保存後副本AUTO角色／場次／狀態已變，未啟動');
