  if(record.group){const until=world.potionCooldowns?.[record.group]?.availableAt;return Number.isFinite(until)&&until>record.cooldownBefore;}
  return Array.isArray(world.buffs)&&world.buffs.some(buff=>buff.sourceSkillId==='consumable:'+record.itemId&&Number.isFinite(buff.expire)&&buff.expire>record.buffBefore);
