      const group=nativePotionGroup(item),until=group?world.potionCooldowns?.[group]?.availableAt:0;if(!Number.isFinite(until)||until>serverNow)return null;
      const value=cfg.type==='hp'?world.player.hp:cfg.type==='sp'?world.player.mp:null,max=cfg.type==='hp'?world.player.maxHp:cfg.type==='sp'?world.player.maxMp:null;
      const low=Number.isFinite(value)&&Number.isFinite(max)&&max>0&&value/max*100<=cfg.threshold,due=cfg.interval>0&&now()-Number(cfg.lastUseAt??context().manualStartedAt??now())>=cfg.interval*1000;
      const quantity=nativeItemQuantity(world,bind.id);return quantity>0&&(low||due)?{slot,itemId:bind.id,group,quantity,cooldownBefore:until,low,bind,props,lastUseAt:cfg.lastUseAt??0}:null;
