// 共用模組/原始碼/文字工具.mjs
/** 將任意值安全轉成文字。 */
function toText(value) {
  return String(value ?? '');
}

/**
 * 將遊戲介面文字轉成便於比對的緊湊格式。
 * 各腳本可依需要決定是否移除中點或統一 CH 頻道格式。
 */
function normalizeCompactText(value, options = {}) {
  const {
    removeMiddleDots = false,
    normalizeChannel = false
  } = options;

  let text = toText(value).replace(/\s+/g, '');
  if (removeMiddleDots) text = text.replace(/[·・]/g, '');
  if (normalizeChannel) text = text.replace(/[Ｃｃ][Ｈｈ][.．]?/g, 'CH.');
  return text.trim();
}

/** 回傳第一個正規化後不是空字串的候選文字。 */
function firstNonEmptyText(values, options = {}) {
  for (const value of values ?? []) {
    const text = normalizeCompactText(value, options);
    if (text) return text;
  }
  return '';
}


// 共用模組/原始碼/元素工具.mjs

const DEFAULT_INTERACTIVE_SELECTOR = [
  'button',
  '[role="button"]',
  'input[type="button"]',
  'input[type="submit"]',
  'a'
].join(', ');

function isHtmlElement(element) {
  return typeof HTMLElement !== 'undefined' && element instanceof HTMLElement;
}

/** 判斷元素是否可見；exclude 可排除腳本自己的介面。 */
function isVisibleElement(element, options = {}) {
  const {
    exclude = () => false,
    requirePointerEvents = false
  } = options;

  if (!isHtmlElement(element) || exclude(element)) return false;
  const style = getComputedStyle(element);
  if (style.display === 'none' || style.visibility === 'hidden') return false;
  if (requirePointerEvents && style.pointerEvents === 'none') return false;
  return element.getClientRects().length > 0;
}

/** 判斷元素是否可見且未停用。 */
function isUsableElement(element, options = {}) {
  if (!isVisibleElement(element, options)) return false;
  return !element.matches(':disabled, [disabled], [aria-disabled="true"]');
}

/** 依優先順序取得元素的可讀標籤。 */
function elementLabel(element, normalizeOptions = {}) {
  if (!element) return '';
  return firstNonEmptyText([
    typeof HTMLInputElement !== 'undefined' && element instanceof HTMLInputElement
      ? element.value
      : '',
    element.innerText,
    element.textContent,
    element.getAttribute?.('aria-label'),
    element.getAttribute?.('title'),
    element.getAttribute?.('alt')
  ], normalizeOptions);
}

/** 取得指定根節點內的常見互動元素。 */
function interactiveElements(root = document, selector = DEFAULT_INTERACTIVE_SELECTOR) {
  return [...root.querySelectorAll(selector)];
}

/** 尋找第一個通過條件且可操作的互動元素。 */
function findInteractive(predicate, options = {}) {
  const {
    root = document,
    selector = DEFAULT_INTERACTIVE_SELECTOR,
    ...visibilityOptions
  } = options;

  return interactiveElements(root, selector).find((element) =>
    isUsableElement(element, visibilityOptions) && predicate(element)
  ) ?? null;
}


