      if (v.breakUntil > t) return { message: `休息中 ${Math.ceil((v.breakUntil-t)/1000)} 秒` };
      if (s.restarted) return t-s.restartAt > 20000 ? stop('重新開始後畫面未切換') : { message: '等待回到隊伍整備' };
      if (!s.restartAt) s.restartAt = t + restartDelay();
