/** 隊長／隊員共用同一個副本任務槽，保留各自來源的設定與成果。 */
function createDungeonAdapter({leaderHost,memberHost}) {
  const sources={leader:createDungeonLeaderAdapter(leaderHost),member:createDungeonMemberAdapter(memberHost)};
  let role='leader';
  function validate(settings={}) {
    if(!settings||typeof settings!=='object'||Array.isArray(settings)||Object.keys(settings).some(k=>!['role','leader','member'].includes(k)))throw new Error('副本設定格式無效');
    if(settings.role!==undefined&&!['leader','member'].includes(settings.role))throw new Error('請選擇副本隊長或隊員');
    sources.leader.validate(settings.leader??{});sources.member.validate(settings.member??{});return true;
  }
  function select(value){if(!sources[value])throw new Error('副本角色無效');role=value;return sources[role];}
  return {
    kind:'dungeon',selfDriven:true,validate,
    getSettings:()=>({role,leader:sources.leader.getSettings(),member:sources.member.getSettings()}),
    start(context){validate(context.settings);select(context.settings.role??'leader').start(context);},
    observe:()=>sources[role].observe(),tick:()=>sources[role].tick(),
    pause:context=>sources[role].pause(context),stop:(context,reason)=>sources[role].stop(context,reason),
    settle:context=>sources[role].settle(context),
    resume(context,checkpoint){select(checkpoint.sourceRole).resume(context,checkpoint);},
    reconcile(pending){return select(pending?.sourceRole??role).reconcile(pending);},
    result:()=>sources[role].result(),
    settings:value=>{if(!sources[value??role])throw new Error('副本角色無效');return sources[value??role].settings();},
    records:value=>{if(!sources[value??role])throw new Error('副本角色無效');return sources[value??role].records();}
  };
}


