const defaultPlans=()=>[[{kind:'daily',count:1},{kind:'battle',count:1}],[{kind:'daily',count:1},{kind:'boss',count:1}],[{kind:'daily',count:1},{kind:'dungeon',count:3},{kind:'boss',count:3},{kind:'battle',count:1}]];
for(let i=0;i<3;i++){const option=document.createElement('option');option.value='plan-'+i;option.textContent='方案'+(i+1);compactPanel.choice.append(option);}
async function executeSelection(rerun=false,restart=false){initializeRole();assertSourcesReadable();if(!controller)throw new Error('等待角色載入');if(restart){if(controller.cleanup||controller.settlement)throw new ControlError('cleanup_running','等待原執行收尾再重新執行');if(controller.pending)throw new ControlError('unknown_result','先核對未明操作再重新執行');if(controller.mode!=='managed'&&controller.active)throw new ControlError('task_busy','先安全暫停目前任務再重新執行');}const selected=compactPanel.choice.value;if(selected.startsWith('plan-')){if(controller.mode==='managed'){
 const savedTask=session.status().manualTask;
 if(rerun&&controller.checkpoint&&savedTask?.planId===selected&&savedTask.runId===controller.checkpoint.context.runId){await session.manualTask({action:'resume',runId:controller.checkpoint.context.runId});notice='已請核心接續原方案';render();return;}
 const plans=store.read(roleId,'settings',{})?.plans??defaultPlans(),steps=plans[Number(selected.slice(5))];validatePlanSteps(steps);const snapshots=steps.map(step=>({kind:step.kind,settings:planStepSettings(step,taskSnapshot(step.kind))}));for(const step of snapshots)controller.adapters.get(step.kind).validate(step.settings);
 await session.manualTask({action:'start',steps:snapshots,options:{planId:selected,farmEnabled:planFarmEnabled(steps),farmSettings:{...localSettings('farm'),limit:1},farmInterrupt:farmInterruptSettings(),team:store.read(roleId,'settings',{})?.routineTeam??null,taskTeams:taskTeamsSnapshot()}});notice='已請核心執行'+'方案'+(Number(selected.slice(5))+1)+'；交接依安全點進行';render();return;
}if(rerun){await routine.resumePlan(selected);}else{applyDraftBoundary();const plans=store.read(roleId,'settings',{})?.plans??defaultPlans();await routine.beginPlan(plans[Number(selected.slice(5))],{planId:selected,farmEnabled:planFarmEnabled(plans[Number(selected.slice(5))]),farmInterrupt:farmInterruptSettings(),team:store.read(roleId,'settings',{})?.routineTeam??null,taskTeams:taskTeamsSnapshot()});}if(!rerun){routine.state.planLabel='方案'+(Number(selected.slice(5))+1);routine.persist();}notice=rerun?'已接續原方案進度':'已開始角色方案';render();return;}if(rerun&&controller.checkpoint?.kind===selected&&controller.checkpoint.context?.settings.manualAuto!==true){if(controller.mode==='managed'){const savedTask=session.status().manualTask;if(savedTask?.planId!==null||savedTask.taskKind!==selected||savedTask.runId!==controller.checkpoint.context.runId)return startLocal(selected,(rerun||restart)&&selected==='daily'?{rerunAll:true}:{});await session.manualTask({action:'resume',runId:controller.checkpoint.context.runId});notice='已請核心接續原單項快照';render();return;}if(!routine.state.steps&&routine.state.currentRun?.runId===controller.checkpoint.context.runId&&routine.state.options?.primaryKind===selected){await routine.resumeSaved();notice='已接續原單項任務與種植插隊安排';}else{await acquireRoleLock();await controller.resume({manual:true});notice='已接續原單項任務';}render();return;}return startLocal(selected,(rerun||restart)&&selected==='daily'?{rerunAll:true}:{});}
